(function () {
      var nav = document.getElementById('nav');
      var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
      var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
      if (hamburger && mobileMenu) {
        hamburger.addEventListener('click', function () {
          var isOpen = mobileMenu.classList.toggle('open');
          hamburger.setAttribute('aria-expanded', isOpen.toString());
          document.body.style.overflow = isOpen ? 'hidden' : '';
        });
        mobileMenu.querySelectorAll('a').forEach(function (link) {
          link.addEventListener('click', function () {
            mobileMenu.classList.remove('open');
            hamburger.setAttribute('aria-expanded', 'false');
            document.body.style.overflow = '';
          });
        });
      }
      if (nav) {
        window.addEventListener('scroll', function () {
          nav.classList.toggle('scrolled', window.scrollY > 10);
        }, { passive: true });
      }
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && mobileMenu && mobileMenu.classList.contains('open')) {
          mobileMenu.classList.remove('open');
          if (hamburger) hamburger.setAttribute('aria-expanded', 'false');
          document.body.style.overflow = '';
        }
      });
      document.querySelectorAll('a.btn--klass[href*="klasswagen.com"]').forEach(function (el) {
        el.addEventListener('click', function () {
          var src = el.id === 'klasswagenMainCta' ? 'hero-primary' : 'inline-card';
          if (window.plausible) plausible('PartnerCarRental-Click', { props: { partner: 'klasswagen', code: 'MATAY', source: src, page: 'car-rental-klasswagen' } });
        });
      });
      var promoCode = 'MATAY';
      var toastEl = document.getElementById('copyToast');
      var toastTimer;
      function showCopyToast(msg) {
        if (!toastEl) return;
        toastEl.textContent = msg;
        toastEl.classList.add('copy-toast--show');
        if (toastTimer) window.clearTimeout(toastTimer);
        toastTimer = window.setTimeout(function () {
          toastEl.classList.remove('copy-toast--show');
        }, 2400);
      }
      document.querySelectorAll('.js-promo-copy').forEach(function (btn) {
        btn.addEventListener('click', function () {
          var src = btn.getAttribute('data-copy-source') || 'promo-strip';
          if (navigator.clipboard && navigator.clipboard.writeText)
            navigator.clipboard.writeText(promoCode).catch(function () {});
          btn.classList.add('promo-copy--copied');
          window.setTimeout(function () { btn.classList.remove('promo-copy--copied'); }, 1400);
          showCopyToast('MATAY הועתק - מדביקים בשדה הקופון');
          if (window.plausible) plausible('PartnerCarRental-CodeCopy', { props: { partner: 'klasswagen', code: promoCode, source: src } });
        });
      });
    })();
